/**
 * API 客户端
 * Phase1 重构后的 API 接口
 */

import Taro from '@tarojs/taro';

const BASE_URL = 'http://127.0.0.1:3001/api';

/** 请求配置 */
interface RequestConfig {
  method?: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
  data?: unknown;
  headers?: Record<string, string>;
}

/** API 响应 */
interface ApiResponse<T = unknown> {
  success: boolean;
  data?: T;
  error?: {
    code: string;
    message: string;
    retryable: boolean;
  };
}

/**
 * 基础请求函数
 */
export async function request<T>(
  url: string,
  config: RequestConfig = {}
): Promise<T> {
  const { method = 'GET', data, headers = {} } = config;

  try {
    const response = await Taro.request({
      url: `${BASE_URL}${url}`,
      method,
      data,
      header: {
        'Content-Type': 'application/json',
        ...headers,
      },
    });

    const result = response.data as ApiResponse<T>;

    if (!result.success) {
      throw new Error(result.error?.message || '请求失败');
    }

    return result.data as T;
  } catch (error) {
    console.error('API 请求失败:', error);
    throw error;
  }
}

/**
 * SSE 流式请求
 */
export function streamRequest(
  url: string,
  onMessage: (data: unknown) => void,
  onError?: (error: Error) => void
): () => void {
  const fullUrl = `${BASE_URL}${url}`;

  // 使用 wx.requestTask 支持流式响应
  const requestTask = Taro.request({
    url: fullUrl,
    method: 'GET',
    header: {
      Accept: 'text/event-stream',
    },
    enableChunked: true,
    success: () => {
      // 流结束
    },
    fail: (err) => {
      onError?.(new Error(err.errMsg));
    },
  });

  // 监听数据块
  let buffer = '';
  requestTask.onChunkReceived?.((res: { data: ArrayBuffer }) => {
    const chunk = new TextDecoder().decode(res.data);
    buffer += chunk;

    // 解析 SSE 事件
    const lines = buffer.split('\n\n');
    buffer = lines.pop() || '';

    for (const line of lines) {
      const event = parseSSEEvent(line);
      if (event) {
        onMessage(event);
      }
    }
  });

  // 返回取消函数
  return () => {
    requestTask.abort?.();
  };
}

/**
 * 解析 SSE 事件
 */
function parseSSEEvent(data: string): unknown | null {
  const lines = data.split('\n');
  let event = '';
  let id = '';
  let payload = '';

  for (const line of lines) {
    if (line.startsWith('event:')) {
      event = line.slice(6).trim();
    } else if (line.startsWith('id:')) {
      id = line.slice(3).trim();
    } else if (line.startsWith('data:')) {
      payload = line.slice(5).trim();
    }
  }

  if (!payload) return null;

  try {
    return {
      event,
      id,
      data: JSON.parse(payload),
    };
  } catch {
    return { event, id, data: payload };
  }
}

